package br.com.confirmacao.professional.access;import br.com.confirmacao.auth.application.*;import br.com.confirmacao.professional.application.ProfessionalService;import br.com.confirmacao.user.domain.*;import br.com.confirmacao.user.infrastructure.UserRepository;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ProfessionalAccessService{private final ProfessionalService professionals;private final UserRepository users;private final PasswordEncoder passwords;private final TokenService tokens;public ProfessionalAccessService(ProfessionalService p,UserRepository u,PasswordEncoder e,TokenService t){professionals=p;users=u;passwords=e;tokens=t;}@Transactional public ProfessionalAccessResult create(String n,String e,String ph,String reg,String timezone,String pass){if(users.existsByEmailIgnoreCase(e))throw new br.com.confirmacao.user.application.UserAlreadyExistsException("Já existe um usuário com este e-mail");var pro=professionals.create(n,e,ph,reg);pro.updateProfile(n,e,ph,reg,null,null,timezone,60,"PRESENTIAL",true);var user=users.save(new User(pro,n,e,passwords.encode(pass),UserRole.PROFESSIONAL));return new ProfessionalAccessResult(pro,user);}@Transactional public AuthenticationResult register(String n,String e,String ph,String reg,String timezone,String pass){var r=create(n,e,ph,reg,timezone,pass);return new AuthenticationResult(tokens.generate(r.user()),tokens.expirationSeconds(),r.user());}}
